/*
 * A039435  Numbers whose base-10 representation has the same nonzero number
 *          of 7's and 8's.
 * https://oeis.org/A039435
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the n-th positive integer whose decimal representation *
 *            has an equal nonzero number of 7's and 8's. (Generated by
 *            scanning integers.)
 * Range:     u8 n <= 4, u16 n <= 50, u32 n <= 50, u64 n <= 50, u128 n <= 50,
 *            big any n
 * Helpers:   grow_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>
#include "../utils/grow_seq.h"

seq_t a(idx_t n)
{
    /* static cache holds all terms found so far, plus a counter of how many
     * have been found (found) and the next integer to examine (cur). */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static idx_t cur = 1;        /* next integer to test */
    static idx_t found = 0;      /* number of terms already in cache */

    /* Generate terms until we have at least n of them. */
    while (found < n)
    {
        /* Grow the cache if necessary. */
        if (cache_len == cache_cap)
            grow_seq(&cache, &cache_cap, cache_cap ? cache_cap * 2 : 16);

        /* Count 7's and 8's in cur. */
        idx_t tmp = cur;
        int c7 = 0, c8 = 0;
        while (tmp > 0)
        {
            int d = tmp % 10;
            if (d == 7) c7++;
            else if (d == 8) c8++;
            tmp /= 10;
        }

        /* If the number satisfies the property, store it. */
        if (c7 == c8 && c7 > 0)
        {
            cache[cache_len++] = (seq_t)cur;
            ++found;
        }

        /* Move on to the next integer. */
        ++cur;
    }

    /* Return the requested term. */
    return cache[n - 1];
}
